class Stack:

	def __init__(self):
		self.items = []

	def isEmpty(self):
		return self.items == []

	def push(self, item):
		self.items.append(item)

	def pop(self):
		return self.items.pop()

	def peek(self):
		return self.items[len(self.items) - 1]

	def size(self):
		return len(self.items)

def untangle(sequence):
	s = Stack()
	for i in sequence:
		if not s.isEmpty():
			if i == s.peek():
				s.pop()
			else:
				s.push(i)
		else:
			s.push(i)
	if not s.isEmpty():
		print('No')
	else:
		print('Yes')
quence = input()
untangle(quence)
